def normalize_text(value):
    decomposed = unicodedata.normalize("NFKD", value)
    without_accents = "".join(
        character for character in decomposed if not unicodedata.combining(character)
    )
    return without_accents.casefold().strip()


def add_default_suggestions(apps, schema_editor):
    suggestion_model = apps.get_model("consultations", "MedicalSuggestion")
    consultation_model = apps.get_model("consultations", "Consultation")
    database = schema_editor.connection.alias

    for old_value, label in (
        ("EMERGENCY", "Urgence"),
        ("SPECIALIST", "Médecin spécialiste"),
        ("HOME", "Orientation à domicile"),
    ):
        consultation_model.objects.using(database).filter(
            destination=old_value
        ).update(destination=label)

    suggestion_model.objects.using(database).bulk_create(
        [
            suggestion_model(
                category=category,
                text=text,
                normalized_text=normalize_text(text),
            )
            for category, text in DEFAULT_SUGGESTIONS
        ]
    )


def remove_default_suggestions(apps, schema_editor):
    suggestion_model = apps.get_model("consultations", "MedicalSuggestion")
    database = schema_editor.connection.alias
    for category, text in DEFAULT_SUGGESTIONS:
        suggestion_model.objects.using(database).filter(
            doctor__isnull=True,
            category=category,
            text=text,
        ).delete()


